int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    const char *pair = in;
    size_t pair_count = 0;

    while (pair && pair_count < max_pairs) {
        const char *eq = strchr(pair, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair);
        keys_out[pair_count] = malloc(klen + 1);
        strncpy(keys_out[pair_count], pair, klen);
        keys_out[pair_count][klen] = '\0';

        const char *quote = strchr(eq + 1, '"');
        if (quote) {
            size_t vlen = (size_t)(strchr(quote + 1, '"') - quote) - 1;
            vals_out[pair_count] = malloc(vlen + 1);
            strncpy(vals_out[pair_count], quote + 1, vlen);
            vals_out[pair_count][vlen] = '\0';
        } else {
            size_t vlen = (size_t)(strchr(eq, ' ') - eq) - 1;
            vals_out[pair_count] = malloc(vlen + 1);
            strncpy(vals_out[pair_count], eq + 1, vlen);
            vals_out[pair_count][vlen] = '\0';
        }

        pair = strchr(eq, ' ');
        if (pair) pair++;
        pair_count++;
    }

    return (int)pair_count;
}

